-- NEWS HUB production content for InfinityFree/MySQL 8 or MariaDB 11.4.
-- Run only after 01-schema-infinityfree.sql and after creating one Admin account.
-- This script inserts 26 categories and 8 curated original summaries with source links.
-- It does not create demo users, demo comments, placeholder articles, or any extra tables.
SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;
START TRANSACTION;
SET @admin_id = (SELECT u.id FROM users u JOIN roles r ON r.id = u.role_id WHERE r.name = 'admin' AND u.status = 'active' ORDER BY u.id ASC LIMIT 1);
SELECT @admin_id AS required_active_admin_user_id;

