INSERT INTO articles (category_id, user_id, title, slug, summary, content, thumbnail, status, is_featured, published_at)
SELECT c.id, @admin_id, 'Việt Nam chính thức tiếp nhận vai trò chủ nhà APEC 2027', 'sample-01-thoi-su', 'Lễ chuyển giao tại Thâm Quyến diễn ra sau Hội nghị Cấp cao APEC lần thứ 33. Việt Nam bắt đầu chuẩn bị chương trình hợp tác khu vực cho năm 2027.', '<p>Ngày 19/11/2026, Việt Nam tiếp nhận vai trò chủ nhà Năm APEC 2027 tại Thâm Quyến (Trung Quốc), trước sự chứng kiến của lãnh đạo 21 nền kinh tế thành viên. Lễ chuyển giao được tổ chức sau khi Hội nghị các Nhà lãnh đạo kinh tế APEC lần thứ 33 kết thúc phần thảo luận và thông qua các văn kiện hợp tác.</p><p>Việc đăng cai không chỉ là nhiệm vụ tổ chức hội nghị. Nước chủ nhà còn điều phối chương trình nghị sự, kết nối các nền kinh tế và tạo điều kiện để doanh nghiệp, cơ quan quản lý cùng trao đổi về thương mại, đầu tư, năng suất và những động lực tăng trưởng mới.</p><p>Việt Nam giới thiệu chủ đề Năm APEC 2027 gắn với tinh thần tự cường, đổi mới sáng tạo và thịnh vượng chung. Ba hướng ưu tiên được nêu gồm nâng cao năng suất, thúc đẩy thương mại – đầu tư khu vực và tăng khả năng tự cường, năng động của các nền kinh tế.</p><p>Hiệu quả của năm APEC sẽ được đánh giá qua những sáng kiến và kết quả hợp tác cụ thể, chứ không chỉ qua quy mô sự kiện. Công tác chuẩn bị trong thời gian tới vì vậy cần gắn đối thoại cấp cao với lợi ích thiết thực của doanh nghiệp và người dân.</p><blockquote><p><strong>Nguồn tham khảo:</strong> <a href="https://vnexpress.net/tong-bi-thu-chu-tich-nuoc-tiep-nhan-vai-tro-chu-nha-apec-2027-5146557.html">VnExpress</a> · 19/11/2026</p></blockquote>', 'seed_world.jpg', 'published', 1, '2026-11-19 12:47:00' FROM categories c WHERE c.slug = 'thoi-su'
UNION ALL
SELECT c.id, @admin_id, 'Lãnh đạo Nga – Mỹ – Trung lần đầu họp thượng đỉnh ba bên', 'sample-05-the-gioi', 'Cuộc gặp bên lề APEC tại Thâm Quyến mở ra cuộc trao đổi trực tiếp giữa ba cường quốc về an ninh, hợp tác và những bất đồng quốc tế.', '<p>Chiều 19/11/2026, lãnh đạo Nga, Mỹ và Trung Quốc tổ chức cuộc gặp ba bên lần đầu bên lề Hội nghị APEC tại Thâm Quyến. Cuộc trao đổi diễn ra trong bối cảnh ba nước có ảnh hưởng lớn đến các vấn đề toàn cầu nhưng vẫn tồn tại khác biệt về nhiều hồ sơ quốc tế.</p><p>Phần phát biểu mở đầu tập trung vào khả năng duy trì đối thoại, giảm căng thẳng và tìm kiếm cách thức hợp tác. Phía Trung Quốc nhấn mạnh việc tăng cường trao đổi cấp cao, duy trì liên lạc trong khủng hoảng và tránh để bất đồng làm gián đoạn các quan hệ kinh tế.</p><p>Vấn đề kiểm soát vũ khí hạt nhân và xung đột Ukraine cũng được nhắc đến trong các phát biểu được VnExpress tường thuật. Tuy nhiên, các tuyên bố công khai tại thời điểm đưa tin chưa đồng nghĩa ba bên đã đạt thỏa thuận chung về những vấn đề này.</p><p>Cuộc gặp được chú ý bởi tính chất chưa từng có ở cấp lãnh đạo ba nước. Tác động thực tế sẽ phụ thuộc vào các bước tiếp xúc tiếp theo, mức độ thống nhất về chương trình nghị sự và việc các bên có chuyển thông điệp đối thoại thành cơ chế hợp tác cụ thể hay không.</p><blockquote><p><strong>Nguồn tham khảo:</strong> <a href="https://vnexpress.net/lanh-dao-nga-my-trung-lan-dau-hop-thuong-dinh-ba-ben-5146594-tong-thuat.html">VnExpress</a> · 19/11/2026</p></blockquote>', 'seed_world.jpg', 'published', 0, '2026-11-19 17:20:00' FROM categories c WHERE c.slug = 'the-gioi'
UNION ALL
SELECT c.id, @admin_id, 'VN-Index giảm phiên thứ ba liên tiếp, lùi xuống dưới 1.700 điểm', 'sample-07-tai-chinh', 'Chỉ số VN-Index mất 13,39 điểm trong phiên 19/11, xuống 1.689,62 điểm; áp lực bán lan rộng trên thị trường.', '<p>Thị trường chứng khoán Việt Nam tiếp tục đi xuống trong phiên 19/11/2026. VN-Index giảm 13,39 điểm, tương đương 0,79%, và đóng cửa tại 1.689,62 điểm, đánh dấu phiên giảm thứ ba liên tiếp và đưa chỉ số xuống dưới mốc 1.700 điểm.</p><p>Diễn biến trong phiên cho thấy áp lực bán xuất hiện trên diện rộng. Một số cổ phiếu vốn hóa lớn thuộc nhóm ngân hàng, bất động sản và công nghệ gây sức ép lên chỉ số, trong khi dòng tiền chưa đủ mạnh để tạo nhịp hồi phục bền vững.</p><p>Khối ngoại tiếp tục bán ròng trong phiên, tập trung tại một số mã có giá trị giao dịch lớn. Các con số trong bản tin phản ánh diễn biến của phiên giao dịch cụ thể, không nên được xem là dự báo cho những phiên tiếp theo.</p><p>Thông tin thị trường chỉ cung cấp bối cảnh tham khảo, không phải khuyến nghị đầu tư. Nhà đầu tư cần tự đánh giá mục tiêu, thời hạn và mức độ chấp nhận rủi ro trước mọi quyết định.</p><blockquote><p><strong>Nguồn tham khảo:</strong> <a href="https://tuoitre.vn/vn-index-giam-3-phien-lien-tiep-ve-duoi-1700-diem-100261119154114635.htm">Tuổi Trẻ Online</a> · 19/11/2026</p></blockquote>', 'seed_business.jpg', 'published', 0, '2026-11-19 16:30:00' FROM categories c WHERE c.slug = 'tai-chinh'
UNION ALL
SELECT c.id, @admin_id, 'VNPT thử nghiệm thiết bị Internet tích hợp AI và Wi‑Fi 8', 'sample-09-cong-nghe', 'VNPT và Qualcomm giới thiệu thiết bị cổng mạng thử nghiệm có AI xử lý ngay tại thiết bị, hỗ trợ tương tác giọng nói và tối ưu kết nối trong gia đình.', '<p>Ngày 19/11/2026, VNPT và Qualcomm công bố phiên bản thử nghiệm VNPT AI Gateway Wi‑Fi 8. Theo Báo Điện tử Chính phủ, sản phẩm là kết quả hợp tác thông qua Trung tâm Xuất sắc VNPT – Qualcomm, hướng tới đưa trí tuệ nhân tạo vào thiết bị mạng tại hộ gia đình.</p><p>Khác với bộ phát Internet chủ yếu chuyển tiếp kết nối, thiết bị được giới thiệu có thể xử lý một số tác vụ AI ngay tại thiết bị biên. Người dùng có thể hỏi bằng tiếng Việt hoặc tiếng Anh về tình trạng mạng, thay đổi một số cấu hình và theo dõi hoạt động kết nối thông qua giao diện cảm ứng hoặc giọng nói.</p><p>Thông tin công bố cũng đề cập các tính năng tối ưu chất lượng dịch vụ, nhận diện thiết bị kết nối và kiểm soát thời gian truy cập Internet của trẻ. Đây là những tính năng hướng đến việc quản lý mạng gia đình thuận tiện hơn, nhưng mức độ hiệu quả thực tế còn cần được đánh giá qua thử nghiệm và triển khai thương mại.</p><p>Nhà sản xuất công bố thiết bị hỗ trợ XGS-PON, Wi‑Fi 8 ba băng tần và xử lý AI tại biên. Các thông số kỹ thuật trong thông cáo là thông tin do đơn vị phát triển công bố; người dùng nên chờ kết quả kiểm thử độc lập và điều kiện cung cấp chính thức trước khi đánh giá hiệu năng.</p><blockquote><p><strong>Nguồn tham khảo:</strong> <a href="https://baochinhphu.vn/vnpt-va-qualcomm-ra-mat-vnpt-ai-gateway-wi-fi-8-the-he-moi-10226111910342727.htm">Báo Điện tử Chính phủ</a> · 19/11/2026</p></blockquote>', 'seed_technology.jpg', 'published', 1, '2026-11-19 10:46:00' FROM categories c WHERE c.slug = 'cong-nghe'
UNION ALL
SELECT c.id, @admin_id, 'U17 World Cup 2026 khởi tranh, Việt Nam lần đầu góp mặt', 'sample-13-the-thao', 'Vòng chung kết U17 World Cup diễn ra tại Qatar từ 19/11 đến 13/12 với 48 đội. U17 Việt Nam lần đầu tham dự và dự kiến gặp Bỉ ở trận ra quân ngày 20/11.', '<p>Vòng chung kết FIFA U17 World Cup 2026 bắt đầu tại Qatar ngày 19/11 và kéo dài đến 13/12. Giải có 48 đội tuyển, chia thành 12 bảng; đây là lần đầu đội tuyển U17 Việt Nam góp mặt ở sân chơi này.</p><p>Việt Nam giành suất tham dự sau khi vượt qua vòng loại châu Á. Theo lịch được VnExpress đăng tải, đội nằm ở bảng G và dự kiến gặp Bỉ ngày 20/11, tiếp đó là New Zealand ngày 23/11 và Mali ngày 26/11.</p><p>Thể thức vòng bảng gồm các trận đấu một lượt. Các đội nhất và nhì bảng cùng tám đội xếp thứ ba có thành tích tốt nhất sẽ giành quyền vào vòng 1/16. Điều đó khiến từng điểm số và hiệu số bàn thắng có ý nghĩa với cơ hội đi tiếp.</p><p>Lần đầu dự giải là cột mốc đáng chú ý với bóng đá trẻ Việt Nam. Bên cạnh kết quả, các trận đấu với những nền bóng đá có truyền thống đào tạo trẻ mạnh cũng là dịp để cầu thủ tích lũy kinh nghiệm quốc tế.</p><blockquote><p><strong>Nguồn tham khảo:</strong> <a href="https://vnexpress.net/fifa-u17-world-cup-2026-khoi-tranh-hom-nay-5146326.html">VnExpress</a> · 19/11/2026</p></blockquote>', 'seed_sports.jpg', 'published', 0, '2026-11-19 05:26:00' FROM categories c WHERE c.slug = 'the-thao'
UNION ALL
SELECT c.id, @admin_id, 'Hà Nội vinh danh 99 thủ khoa tốt nghiệp năm 2026', 'sample-21-giao-duc', 'Lễ tuyên dương tại Văn Miếu – Quốc Tử Giám ghi nhận 99 thủ khoa tốt nghiệp các trường đại học và học viện trên địa bàn Thủ đô.', '<p>Tối 18/11/2026, Hà Nội tổ chức lễ tuyên dương 99 thủ khoa xuất sắc tốt nghiệp từ các trường đại học và học viện trên địa bàn thành phố. Sự kiện diễn ra tại Văn Miếu – Quốc Tử Giám, địa điểm gắn với truyền thống hiếu học và tôn vinh người tài.</p><p>Hoạt động tuyên dương nhằm ghi nhận nỗ lực học tập, nghiên cứu và rèn luyện của sinh viên trong suốt quá trình học đại học. Đây cũng là dịp để thành phố giới thiệu những gương mặt trẻ có thành tích nổi bật, đồng thời khuyến khích tinh thần học tập và cống hiến.</p><p>Việc vinh danh chỉ là bước đầu. Để nguồn nhân lực trẻ phát huy năng lực lâu dài, các cơ sở đào tạo, cơ quan công quyền và doanh nghiệp cần tiếp tục tạo môi trường làm việc, nghiên cứu và đổi mới sáng tạo phù hợp.</p><p>Thông tin về buổi lễ được NEWS HUB biên tập lại từ bản tin của VietnamPlus. Danh sách và thông tin chi tiết về từng cá nhân nên được đối chiếu với đơn vị tổ chức.</p><blockquote><p><strong>Nguồn tham khảo:</strong> <a href="https://www.vietnamplus.vn/99-thu-khoa-xuat-sac-duoc-vinh-danh-tai-van-mieu-quoc-tu-giam-post1149254.vnp">VietnamPlus</a> · 18/11/2026</p></blockquote>', 'seed_education.jpg', 'published', 0, '2026-11-18 21:59:00' FROM categories c WHERE c.slug = 'giao-duc'
UNION ALL
SELECT c.id, @admin_id, 'Thầy giáo mầm non bền bỉ vượt qua định kiến nghề nghiệp', 'sample-33-doi-song', 'Câu chuyện về một giáo viên nam gắn bó nhiều năm với bậc học mầm non cho thấy sự kiên trì và chuyên môn có thể giúp thay đổi định kiến.', '<p>Nhân dịp Ngày Nhà giáo Việt Nam 20/11, VnExpress giới thiệu câu chuyện về thầy Nguyễn Thanh Bách, giáo viên Trường Mầm non Na Sầm, tỉnh Lạng Sơn. Thầy đã gắn bó với công việc chăm sóc và giáo dục trẻ nhỏ trong khoảng tám năm, dù lựa chọn nghề từng khiến thầy gặp không ít định kiến.</p><p>Những công việc hằng ngày của giáo viên mầm non đòi hỏi sự kiên nhẫn và quan sát tỉ mỉ: hỗ trợ trẻ trong sinh hoạt, tổ chức hoạt động học tập, chăm sóc từng em theo độ tuổi và khả năng. Với trẻ chậm nói hoặc cần thêm thời gian thích nghi, sự tương tác thường xuyên và cách tiếp cận phù hợp có ý nghĩa đặc biệt.</p><p>Bài viết cho biết thầy Bách từng được giao nhiệm vụ quản lý ở trường, sau đó trở lại công việc giảng dạy khi các cơ sở mầm non được sắp xếp lại. Thầy cho rằng điều quan trọng nhất với nghề vẫn là sự yêu trẻ và niềm tin của phụ huynh.</p><p>Câu chuyện nhắc lại rằng năng lực nghề nghiệp không nên bị đánh giá qua giới tính. Chất lượng chăm sóc, phương pháp sư phạm và sự an toàn của trẻ mới là những tiêu chí cần được đặt lên hàng đầu.</p><blockquote><p><strong>Nguồn tham khảo:</strong> <a href="https://vnexpress.net/thay-giao-vuot-dinh-kien-con-trai-di-day-mam-non-5146559.html">VnExpress</a> · 19/11/2026</p></blockquote>', 'seed_lifestyle.jpg', 'published', 0, '2026-11-19 14:09:00' FROM categories c WHERE c.slug = 'doi-song'
UNION ALL
SELECT c.id, @admin_id, 'Không khí lạnh gây rét ở miền Bắc, miền Trung đề phòng mưa lớn', 'sample-03-moi-truong', 'Dự báo ngày 19/11 cho biết Bắc Bộ và Bắc Trung Bộ chuyển rét; một số khu vực miền Trung có nguy cơ mưa to, dông và sạt lở.', '<p>Theo bản tin thời tiết ngày 19/11/2026 của VietnamPlus, không khí lạnh đã ảnh hưởng đến phần lớn Bắc Trung Bộ và một số nơi ở Tây Bắc Bộ. Nhiệt độ thấp nhất dự báo tại Bắc Bộ và Bắc Trung Bộ phổ biến 15–18°C; vùng núi Bắc Bộ khoảng 12–15°C, vùng núi cao có nơi dưới 10°C.</p><p>Tại Hà Nội, dự báo có lúc có mưa và trời rét. Trên biển, gió Đông Bắc mạnh và sóng lớn được cảnh báo ở một số vùng biển phía Bắc, có thể ảnh hưởng đến hoạt động tàu thuyền.</p><p>Đáng chú ý, từ chiều 19/11 đến những ngày tiếp theo, khu vực từ Quảng Trị đến Đà Nẵng và phía Đông Quảng Ngãi được dự báo có mưa vừa, mưa to, cục bộ mưa rất to. Mưa lớn có thể làm tăng nguy cơ ngập úng, lũ quét ở suối nhỏ và sạt lở trên sườn dốc.</p><p>Đây là thông tin dự báo tại thời điểm phát hành, không phải ghi nhận lượng mưa đã xảy ra. Người dân ở khu vực được cảnh báo nên theo dõi cập nhật của cơ quan khí tượng và thông báo ứng phó tại địa phương.</p><blockquote><p><strong>Nguồn tham khảo:</strong> <a href="https://www.vietnamplus.vn/thoi-tiet-ngay-1911-mien-bac-chuyen-ret-vung-nui-cao-co-noi-ret-dam-post1149266.vnp">VietnamPlus</a> · 19/11/2026</p></blockquote>', 'seed_world.jpg', 'published', 0, '2026-11-19 06:15:00' FROM categories c WHERE c.slug = 'moi-truong';

SELECT COUNT(*) AS published_editorial_articles FROM articles WHERE slug IN ('sample-01-thoi-su', 'sample-05-the-gioi', 'sample-07-tai-chinh', 'sample-09-cong-nghe', 'sample-13-the-thao', 'sample-21-giao-duc', 'sample-33-doi-song', 'sample-03-moi-truong');
